contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address other, uint otherAmount, uint callerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(other != address(this), "other must differ from caller");
        require(address(this).balance >= callerAmount, "insufficient test balance");

        uint256 otherBefore = c.balances(other); if (__ESBMC_reverted()) return;
        require(otherBefore == 0, "other already has a balance");

        c.withdraw(); if (__ESBMC_reverted()) return;

        assert(c.balances(other) == otherBefore);
    }
}

