// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address other, uint256 otherAmount, uint256 callerAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(other != address(this));
        vm.assume(address(this).balance >= callerAmount);
        uint256 otherBefore;
        try c.balances(other) returns (uint256 __r) { otherBefore = __r; } catch { return; }
        vm.assume(otherBefore == 0);
        try c.withdraw() {} catch { return; }
        assertTrue(c.balances(other) == otherBefore);
    }

    function testFuzz_run(address other, uint256 otherAmount, uint256 callerAmount) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(other, otherAmount, callerAmount);
    }

    receive() external payable {}
}
